  ('989958023138534407', 'Braid', 2019, 'Thriller, Horror, Mystery', 'Robert Lopez, Michael Toscano, Mitzi Peirone', 'Mitzi Peirone', 'Madeline Brewer, Imogen Waterhouse, Sarah Hay, Scott Cohen, Clyde Baldo, Rob Leo Roy, Zack Calhoon, Lenore Wolf', null, 'Two drug dealers on the lam seek refuge inside their mentally unstable friend’s mansion. But in order to stay, they have to participate in her elaborate, and increasingly dangerous, game of permanent make-believe.', 'Two drug dealers on the lam seek refuge inside their mentally unstable friend’s mansion. But in order to stay, they have to participate in her elaborate, and increasingly dangerous, game of permanent make-believe.', 'https://image.tmdb.org/t/p/w500/sp8dzGdwBh3cDU8ygyjtoejfZzI.jpg', 'tmdb:movie:510284'),
  ('334768201110408194', 'Brain Damage', 1988, 'Horror, Comedy', 'Greg Lamberson, Frank Henenlotter, Bruce Torbet', 'Frank Henenlotter', 'Rick Hearst, Jennifer Lowry, Gordon MacDonald, Theo Barnes, John Zacherle, Lucille Saint-Peter, Vicki Darnell, Joseph Gonzalez', 'R', 'Brian comes under the addictive spell of a parasite with the ability to induce euphoric hallucinations in its hosts.', 'Brian comes under the addictive spell of a parasite with the ability to induce euphoric hallucinations in its hosts.', 'https://image.tmdb.org/t/p/w500/nNJbQXlut92RIpcnPyoICzdJvJs.jpg', 'tmdb:movie:27814'),
